import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading to prevent flickering
const { fontFamily: interFamily } = loadInter();



export type WorkshopButtonProps = Record<string, any>;

const WorkshopButton: React.FC<WorkshopButtonProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 5,
  buttonText = "FREE 30 Minute Workshop",
  buttonColor = "#3b82f6",
  glowColor = "#60a5fa",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // 1. Button Entrance Animation
  const entrance = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
    durationInFrames: 30,
  });

  // 2. Continuous Pulsing Aura
  const pulseScale = interpolate(
    Math.sin(frame / 8),
    [-1, 1],
    [1.0, 1.15]
  );
  const glowOpacity = interpolate(
    Math.sin(frame / 8),
    [-1, 1],
    [0.3, 0.7]
  );

  // 3. Click Sequence Timing (Frames 60 to 70)
  const pressDown = interpolate(frame, [60, 65], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  // Spring back up after the click is fully pressed
  const releaseUp = spring({
    frame: Math.max(0, frame - 70),
    fps,
    config: { damping: 12, stiffness: 300 },
  });

  // Calculate the composite click effect (0 -> 1 -> 0)
  const buttonClickEffect = pressDown * 0.05 - releaseUp * 0.05;
  const finalButtonScale = entrance * (1 - buttonClickEffect);

  const cursorClickEffect = pressDown * 0.15 - releaseUp * 0.15;
  const finalCursorScale = 1 - cursorClickEffect;

  // 4. Cursor Trajectory
  const cursorStartX = width * 0.7;
  const cursorStartY = height * 1.2; // Starts below canvas
  const cursorTargetX = width * 0.5 + 30; // Aiming slightly off-center on the button
  const cursorTargetY = height * 0.5 + 20;
  const cursorEndX = width * 1.2; // Exits to the right
  const cursorEndY = height * 0.8;

  const cursorMoveInProgress = interpolate(frame, [20, 50], [0, 1], {
    easing: Easing.bezier(0.25, 1, 0.5, 1), // ease-out
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const cursorMoveOutProgress = interpolate(frame, [90, 120], [0, 1], {
    easing: Easing.bezier(0.5, 0, 0.75, 0), // ease-in
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  let currentCursorX = cursorStartX;
  let currentCursorY = cursorStartY;

  // Determine cursor position based on timeline
  if (frame < 90) {
    currentCursorX = interpolate(cursorMoveInProgress, [0, 1], [cursorStartX, cursorTargetX]);
    currentCursorY = interpolate(cursorMoveInProgress, [0, 1], [cursorStartY, cursorTargetY]);
  } else {
    currentCursorX = interpolate(cursorMoveOutProgress, [0, 1], [cursorTargetX, cursorEndX]);
    currentCursorY = interpolate(cursorMoveOutProgress, [0, 1], [cursorTargetY, cursorEndY]);
  }

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* Wrapper to handle base scaling of both Aura and Button synchronously */}
      <div
        style={{
          position: "absolute",
          transform: `scale(${finalButtonScale})`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Glowing Aura */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backgroundColor: glowColor,
            borderRadius: 200, // Large enough to create a pill shape
            filter: "blur(40px)",
            opacity: glowOpacity,
            transform: `scale(${pulseScale})`,
            transition: "none",
          }}
        />

        {/* The Clickable Button */}
        <div
          style={{
            position: "relative",
            padding: "40px 80px",
            backgroundColor: buttonColor,
            borderRadius: 200,
            boxShadow:
              "0 20px 40px rgba(0,0,0,0.4), inset 0 2px 4px rgba(255,255,255,0.4)",
            zIndex: 10,
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: interFamily,
              fontSize: 56,
              fontWeight: 800,
              color: textColor,
              whiteSpace: "nowrap",
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {buttonText}
          </span>
        </div>
      </div>

      {/* Mouse Cursor */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `translate(${currentCursorX}px, ${currentCursorY}px) scale(${finalCursorScale})`,
          zIndex: 20,
          transition: "none",
        }}
      >
        <svg
          width="70"
          height="70"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          style={{
            filter: "drop-shadow(0px 10px 15px rgba(0,0,0,0.4))",
            transition: "none",
          }}
        >
          <path
            d="M5.5 2.5L20.5 10.5L12.5 12.5L16.5 20.5L12.5 22.5L8.5 14.5L3.5 18.5V2.5Z"
            fill="white"
            stroke="black"
            strokeWidth="1.5"
            strokeLinejoin="round"
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default WorkshopButton;